def _data() -> None:
    """1. Certifications: a summary like "Credential ID X" moves into credential_id (the summary
       is cleared only when it held nothing else).
    2. Candidate header: full name, email and location are cleared (the user fills them)."""
    import json
    import re

    conn = op.get_bind()
    for item_id, summary in conn.exec_driver_sql(
        "select id, summary from experience_item where kind = 'certification' "
        "and summary is not null and credential_id is null"
    ).all():
        m = re.fullmatch(r"\s*(?:credential\s*id|id)\s*[:#]?\s*(\S+)\s*", summary or "", re.I)
        if m:
            conn.exec_driver_sql(
                "update experience_item set credential_id = ?, summary = null where id = ?",
                (m.group(1), item_id),
            )
    row = conn.exec_driver_sql("select value from app_setting where key = 'profile'").first()
    if row:
        value = json.loads(row[0]) if isinstance(row[0], str) else dict(row[0])
        for key in ("full_name", "email", "based_in"):
            value[key] = ""
        value.setdefault("phone", "")
        value.setdefault("links", [])
        conn.exec_driver_sql(
            "update app_setting set value = ? where key = 'profile'", (json.dumps(value),)
        )




